which go && go version; T=$(mktemp -d); cp -r /private/tmp/claude-501/-Users-luisnascimento-github-lcnascimento-ai-foundation/310eb6e8-2673-411c-a5a1-b86f5ca4ff04/scratchpad/runs/a-index-references/s6-speedup-r1/{go.mod,parser} $T/; cat > $T/parser/b_test.go <<'EOF'
package parser
import ("strings";"testing";"reflect")
var lines = []string{"a,b,c", "id,name,email,created_at,price,qty,sku,notes", "", "x", ",,,"}
var sink []string
func TestSame(t *testing.T){ for _,l:=range lines{ if !reflect.DeepEqual(Fields(l), strings.Split(l,",")){t.Fatal(l)} } }
func BenchmarkOld(b *testing.B){ l:=lines[1]; for i:=0;i<b.N;i++{ sink=strings.Split(l,",") } }
